PREFIX brick: <http://brickschema.org/schema/1.2/Brick#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT DISTINCT ?z WHERE {
  ?z rdfs:label "Perimeter_bot_ZN_2" .
}

PREFIX brick: <http://brickschema.org/schema/1.2/Brick#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT DISTINCT ?z ?label WHERE {
  ?z rdfs:label ?label .
  FILTER(CONTAINS(?label, "Perimeter"))
}

PREFIX brick: <http://brickschema.org/schema/1.2/Brick#>
SELECT ?p WHERE {
  ?p a brick:Air_TemperatureSensor .
} LIMIT 5
